  // --- WORKFLOW SWITCHER ---

  switchWorkflow(viewId) {
    this.activeWorkflow = viewId;

    const buttons = document.querySelectorAll('.workflow-tabs .wf-btn');
    buttons.forEach(btn => {
      if (btn.getAttribute('data-view') === viewId) {
        btn.classList.add('active');
      } else {
        btn.classList.remove('active');
      }
    });

    const sections = document.querySelectorAll('.view-section');
    sections.forEach(sec => sec.classList.remove('active'));

    const targetView = document.getElementById(`view-${viewId}`);
    if (targetView) {
      targetView.classList.add('active');
    }

    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  // --- AUDIO & DOSSIÊ EXPORT ---

  togglePlayRoteiroAudio() {
    if (this.isSpeechPlaying) {
      this.stopRoteiroAudio();
      return;
    }

    const rot = this.activePauta.roteiro;
    const fullText = `${rot.hook || rot.abertura}. ${rot.aconteceu}. ${rot.contexto}. ${rot.numeros || ''}. ${rot.analise}. ${rot.oQueAconteceAgora || rot.oquevem}. ${rot.fechamento || rot.encerramento}`;

    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      this.speechUtterance = new SpeechSynthesisUtterance(fullText);
      this.speechUtterance.lang = 'pt-BR';
      this.speechUtterance.rate = 1.05;
      
      const voices = window.speechSynthesis.getVoices();
      const ptVoice = voices.find(v => v.lang.includes('pt') || v.lang.includes('PT'));
      if (ptVoice) this.speechUtterance.voice = ptVoice;

      this.speechUtterance.onend = () => {
        this.isSpeechPlaying = false;
        const btn = document.getElementById('btnAudioPlay');
        if (btn) btn.innerHTML = '<span>▶️</span> Ouvir Roteiro';
      };

      window.speechSynthesis.speak(this.speechUtterance);
      this.isSpeechPlaying = true;
      const btn = document.getElementById('btnAudioPlay');
      if (btn) btn.innerHTML = '<span>⏸️</span> Pausar';
      this.showToast("🎙️ Leitura dinâmica em português iniciada!");
    } else {
      this.showToast("Simulação de áudio não suportada pelo navegador.");
    }
  }

  stopRoteiroAudio() {
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
    }
    this.isSpeechPlaying = false;
    const btn = document.getElementById('btnAudioPlay');
    if (btn) btn.innerHTML = '<span>▶️</span> Ouvir Roteiro';
  }

  copyRoteiroText() {
    const rot = this.activePauta.roteiro;
    const text = `SPORT 5 AI — ROTEIRO EDITORIAL (5 MINUTOS)\nPAUTA: ${this.activePauta.title}\nESPORTE: ${this.activePauta.sport} | DATA DO FATO: ${this.activePauta.dataAconteceu}\nFONTE HOMOLOGADA: ${this.activePauta.source}\n\n[0:00 - 0:15 | ABERTURA / HOOK]\n${rot.hook || rot.abertura}\n\n[0:15 - 1:00 | O QUE ACONTECEU]\n${rot.aconteceu}\n\n[1:00 - 2:00 | CONTEXTO]\n${rot.contexto}\n\n[2:00 - 2:45 | NÚMEROS E DADOS]\n${rot.numeros || this.activePauta.stats}\n\n[2:45 - 3:45 | ANÁLISE TÁTICA]\n${rot.analise}\n\n[3:45 - 4:30 | O QUE ACONTECE AGORA]\n${rot.oQueAconteceAgora || rot.oquevem}\n\n[4:30 - 5:00 | FECHAMENTO]\n${rot.fechamento || rot.encerramento}`;

    navigator.clipboard.writeText(text);
    this.showToast("Roteiro copiado para a área de transferência!");
  }

  copyYoutubeDescription() {
    const yt = this.activePauta.youtube || {};
    const text = `${yt.titulo}\n\n${yt.descricao}\n\nTags: ${(yt.tags || []).join(', ')}`;
    navigator.clipboard.writeText(text);
    this.showToast("Metadados do YouTube copiados!");
  }

  exportFullProject() {
    const p = this.activePauta;
    const dossie = {
      sistema: "SPORT 5 AI V2.5 — LIVE NEWSROOM + FACT CHECK",
      exportadoEm: new Date().toISOString(),
      dossiePauta: {
        id: p.id,
        titulo: p.title,
        esporte: p.sport,
        campeonato: p.championship,
        atletaEquipe: p.athlete,
        datas: {
          aconteceu: p.dataAconteceu,
          publicado: p.dataPublicado,
          atualizado: p.dataAtualizado
        },
        scores: {
          editorial: p.scoreEditorial,
          confiabilidade: p.scoreConfiabilidade,
          breakdownEditorial: p.scoreEditorialBreakdown
        },
        statusVerificacao: p.statusVerificacao,
        aprovacaoEditorial: p.workflowStatus,
        inteligenciaEditorial: p.editorialIntelligence,
        auditoriaPorAfirmacao: p.auditoriaAfirmacoes,
        auditoriaDeFontes: p.auditoriaFontes,
        pesquisaProfunda10D: p.pesquisaProfunda10,
        roteiro5Min: p.roteiro,
        auditoriaRoteiro: p.auditoriaRoteiro,
        titulosSugeridos: p.titulos,
        shorts3Versoes: p.shorts,
        thumbnailStudio: p.thumbnail,
        storyboardCenas: p.storyboard,
        youtubeMetadata: p.youtube
      }
    };

    const blob = new Blob([JSON.stringify(dossie, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `dossie_sport5_${p.id}_v25.json`;
    a.click();
    this.showToast("📥 Dossiê completo da pauta exportado em JSON com sucesso!");
  }

